{"command":"perl -e '
open F, "<", "/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat" or die $!;
binmode F;
$data = do { local $/; <F> };
close F;
print "size ".length($data)."\n";
my $pos=0;
while (($pos = index($data, "PK\x03\x04", $pos)) != -1) { print "local header at $pos\n"; $pos++; last if $pos>20; }
$pos=0; my $c=0;
while (($pos = index($data, "PK", $pos)) != -1) {
  $h = substr($data,$pos,4);
  printf "PK at %d : %s\n", $pos, unpack("H*", $h);
  $pos++;
  last if ++$c>20;
}
# find EOCD
$pos=0; $c=0;
while (($pos = index($data, "PK\x05\x06", $pos)) != -1) { print "EOCD at $pos\n"; $pos++; last if ++$c>10; }
# dump around local header
$off = index($data, "PK\x03\x04");
print "dump around $off:\n";
$ctx = substr($data, $off, 200);
for ($i=0;$i<length($ctx);$i+=16){
  $chunk=substr($ctx,$i,16);
  printf "%08d: %s |%s|\n", $off+$i, unpack("H*",$chunk), $chunk =~ s/[^ -~]/./gr;
}
'
echo "=== grep offsets ==="
grep -a -b -o "PK" /app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat | head -n 20","description":"Find zip headers offsets"}

{"command":"perl -e '
open F, "<", "/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat" or die $!;
binmode F; $d = do { local $/; <F> }; close F;
print "size ".length($d)."\n";
my $pos=0; my $n=0;
while (($pos = index($d, "PASSWORD=", $pos)) != -1) {
  $n++;
  $ctx = substr($d, $pos, 60);
  $hex = unpack("H*", $ctx);
  # printable
  ($txt = $ctx) =~ s/[^ -~]/./g;
  printf "Occ #%d at offset %d:\n  ascii: %s\n  hex: %s\n", $n, $pos, $txt, $hex;
  $pos+=9;
  last if $n>50;
}
print "total $n\n";
'
