for($i=0;$i<length($ctx);$i+=16){$c=substr($ctx,$i,16); printf "%08d: %s |%s|\n",$off-200+$i,unpack("H*",$c),$c=~s/[^ -~]/./gr;}
print "EOCD parse:\n";
$e=substr($d,$off,22); print unpack("H*",$e),"\n";
'","description":"Find all PASSWORD occurrences in disk image"}

{"command":"perl -e '
open F,"<","/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat" or die; binmode F; $d=do{local $/;<F>};
for $off (3145632, 3145600) {
  print "=== dump around $off ===\n";
  $ctx=substr($d,$off,250);
  for($i=0;$i<length($ctx);$i+=16){$c=substr($ctx,$i,16); printf "%08d: %s |%s|\n",$off+$i,unpack("H*",$c),$c=~s/[^ -~]/./gr;}
}
# also check local header at 1048576 full parse
print "=== local at 1048576 parse ===\n";
$off=1048576; $h=substr($d,$off,60); print unpack("H*",$h),"\n";
# parse fields: signature 4, ver 2, flag 2, method 2, time 2, date 2, crc 4, comp 4, uncomp 4, fnlen 2, extralen 2
@f = unpack("V v v v v v V V V v v", substr($d,$off,0+30));
print "fields: @f\n";
print "fname: ", substr($d,$off+30, $f[9]), "\n";
print "extra len $f[10]\n";
$dat_off = $off+30+$f[9]+$f[10];
print "data off $dat_off\n";
print "data 50: ", unpack("H*", substr($d,$dat_off,50)), "\n";
print substr($d,$dat_off,50)=~s/[^ -~]/./gr, "\n";
# second zip at 3145632
print "=== local at 3145632 parse ===\n";
$off=3145632; $h=substr($d,$off,60); print unpack("H*",$h),"\n";
@f = unpack("V v v v v v V V V v v", substr($d,$off,0+30));
print "fields: @f\n";
print "fname: ", substr($d,$off+30, $f[9]), "\n";
print "extra len $f[10]\n";
$dat_off = $off+30+$f[9]+$f[10];
print "data off $dat_off\n";
print "data 50 hex: ", unpack("H*", substr($d,$dat_off,60)), "\n";
$c=substr($d,$dat_off,60); print $c=~s/[^ -~]/./gr, "\n";
'
","description":"Parse both zip headers"}

