{"command":"perl -e '
use File::Glob qw(:glob);
for $f (glob("/app/varsea/*/*.bin")) {
  open FH,"<",$f or die; binmode FH; $d=do{local $/;<FH>}; close FH;
  printf "%s size %d\n", $f, length($d);
  for $pat ("PASSWORD=", "8XD", "W54", "launchcode", "PK") {
    $c=0; $pos=0;
    while(($pos=index($d,$pat,$pos))!=-1){$c++; $pos+=length($pat);}
    print "  $pat: $c\n";
  }
  # hex dump first 64
  print "  head hex: ", unpack("H*",substr($d,0,32)), "\n";
  # entropy quick?
}
print "=== check dat for 8XD/W54/PASSWORD counts ===\n";
open F,"<","/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat" or die; binmode F; $d=do{local $/;<F>};
for $pat ("PASSWORD=","8XD","W54","launchcode"){$c=0;$pos=0;while(($pos=index($d,$pat,$pos))!=-1){$c++;$pos+=length($pat);} print " $pat: $c\n";}
'
echo "=== foremost check ==="
foremost -h 2>&1 | head -n 20
echo "=== tsk_recover help ==="
tsk_recover 2>&1 | head -n 20
echo "=== fls on dat ==="
fls /app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat 2>&1 | head -n 20
","description":"Check bins and tool capabilities"}

