{"command":"perl -e '
open F,"<","/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat" or die; binmode F; $d=do{local $/;<F>};
$off=3145741;
$h=substr($d,$off,46);
@f=unpack("V v v v v v v V V V v v v v v V V", $h);
print join(",", map {sprintf "%d(0x%x)",$_,$_} @f),"\n";
print "sig $f[0]\n";
print "madeby $f[1] need $f[2] flag $f[3] method $f[4] time $f[5] date $f[6] crc $f[7] comp $f[8] uncomp $f[9] fnlen $f[10] extralen $f[11] commentlen $f[12] diskstart $f[13] intattr $f[14] extattr $f[15] localoff $f[16]\n";
print "fname: ", substr($d,$off+46,$f[10]),"\n";
print "localoff field = $f[16]\n";
# dump local at that offset? localoff is relative to start of zip disk? For single disk, relative to zip start. Zip start = central - localoff? Actually localoff is offset from start of zip.
# So zip start = central - localoff - ??? Lets compute implied local header position if zip start is S: S+localoff = local header pos. We know central = S + localoff_of_central? No central pos = S + something. Hmm EOCD says cd offset = 0x6d=109, so S = central - 109 = 3145632. Then local header should be at S+localoff.
$central=$off;
$S=$central - 0x6d;
print "S implied $S\n";
print "local header implied at ", $S+$f[16], "\n";
$lh=$S+$f[16];
$ctx=substr($d,$lh,80);
print "at implied LH hex: ", unpack("H*",$ctx),"\n";
print "ascii: ", $ctx=~s/[^ -~]/./gr, "\n";
# also check local at 1048576 offset relative to S?
print "1048576 - S = ", 1048576-$S, "\n";
'
","description":"Parse central directory entry"}

