# Build CRC32 table IEEE
@tbl = ();
for $i (0..255) {
  $c=$i;
  for (0..7) { $c = ($c & 1) ? (0xEDB88320 ^ ($c >> 1)) : ($c >> 1); }
  $tbl[$i]=$c;
}
sub crc32 {
  my ($s)=@_;
  my $crc=0xFFFFFFFF;
  for $ch (unpack("C*", $s)) { $crc = $tbl[($crc ^ $ch) & 0xFF] ^ ($crc >> 8); }
  return ($crc ^ 0xFFFFFFFF) & 0xFFFFFFFF;
}
$target = 0xB0725DC4;
printf "target %08X (%d)\n", $target, $target;
# verify with known? test "123456789" should be CBF43926
printf "test %08X (expect CBF43926)\n", crc32("123456789");
$head="8XDP5Q2RT9Z";
$tail="K7VB34V4WW54";
print "head len ".length($head)." tail len ".length($tail)."\n";
@chars = ("A".."Z","0".."9");
for $m (@chars) {
  $pwd = $head.$m.$tail;
  $file = "PASSWORD=".$pwd."\n";
  $c = crc32($file);
  if ($c == $target) {
    print "MATCH mid=$m pwd=$pwd file CRC ".sprintf("%08X",$c)."\n";
  }
}
print "done single-mid\n";
# also try 2-mid in case tail is 11
print "=== try tail 11 (drop K) with 2 mids ===\n";
$tail2="7VB34V4WW54";
for $a (@chars){ for $b (@chars){
  $pwd=$head.$a.$b.$tail2;
  $file="PASSWORD=".$pwd."\n";
  if (crc32($file)==$target){ print "MATCH2 $pwd\n"; }
}}
print "done2\n";
'
","description":"Brute-force missing password char via CRC"}

