open F,"<","/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat" or die; binmode F; $d=do{local $/;<F>};
$len=length($d);
print "len $len sectors ".($len/512)."\n";
# check boot sig at each 512
$count=0;
for($off=0;$off<$len;$off+=512){
  if(substr($d,$off+510,2) eq "\x55\xAA"){ print "boot sig at $off\n"; $count++; last if $count>5; }
}
print "boot check done\n";
# check for FAT strings, NTFS, EXT superblock magic 0x53EF at 1080
for $off (1024, 1080, 0, 512, 1024+0, 2048, 4096) {
  $magic = substr($d,$off+56,2) if $off==1024;
}
# EXT magic at 1024+56
print "ext magic at 1080: ", unpack("H*",substr($d,1080,2)), " (expect 53ef)\n";
# check for exFAT, etc.
print "first sector hex: ", unpack("H*",substr($d,0,64)),"\n";
print "sector 2048 hex: ", unpack("H*",substr($d,2048*512,64)),"\n" if $len>2048*512;
# check each bin for boot sig?
use File::Glob qw(:glob);
for $f (glob("/app/varsea/*/*.bin")){
  open FH,"<",$f or die; binmode FH; $b=do{local $/;<FH>};
  print "$f len ".length($b)." head ".unpack("H*",substr($b,0,16))." tail ".unpack("H*",substr($b,-16))."\n";
}
'
","description":"Check filesystem signatures"}

