open F,"<","/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat" or die; binmode F; $d=do{local $/;<F>};
# find all [A-Z0-9]{10,} runs
$n=0;
while($d =~ /[A-Z0-9]{10,}/g){
  $m=$&; $pos=pos($d)-length($m);
  # only print those near PASSWORD or with 8XD/W54 or len>=20
  if(length($m)>=20 || $m=~/8XD/ || $m=~/W54/){
    print "run len ".length($m)." at $pos: $m\n";
    $n++;
    last if $n>30;
  }
}
print "done runs, total printed $n\n";
# count all 8XD and W54 already done: 2 each
# Now find all PASSWORD= with 30 bytes hex
$pos=0;
while(($pos=index($d,"PASSWORD=",$pos))!=-1){
  $ctx=substr($d,$pos,50);
  print "PWD at $pos hex ".unpack("H*",substr($d,$pos,40))."\n";
  $pos+=9;
}
'
echo "=== bins uppercase runs ==="
perl -e '
use File::Glob qw(:glob);
for $f (glob("/app/varsea/*/*.bin")){
  open FH,"<",$f or die; binmode FH; $b=do{local $/;<FH>};
  print "== $f ==\n";
  $n=0;
  while($b =~ /[A-Z0-9]{8,}/g){ print " run ".length($&)." at ".(pos($b)-length($&)).": $&\n"; last if ++$n>10; }
  print " done $n\n";
}
'","description":"Find long uppercase runs"}

