{"command":"perl -e '
@tbl=(); for $i (0..255){$c=$i; for(0..7){$c=($c&1)?(0xEDB88320^($c>>1)):($c>>1);} $tbl[$i]=$c;}
sub crc32{my($s)=@_; my $crc=0xFFFFFFFF; for $ch (unpack("C*",$s)){$crc=$tbl[($crc^$ch)&0xFF]^($crc>>8);} return ($crc^0xFFFFFFFF)&0xFFFFFFFF;}
$target=0xB0725DC4;
$base="REDACTED00000000000000000236";
print "base $base len ".length($base)." crc ".sprintf("%08X",crc32("PASSWORD=$base\n"))."\n";
@chars=("A".."Z","0".."9");
# try 1-char mutations
$found=0;
for $pos (0..length($base)-1){
  $orig=substr($base,$pos,1);
  for $c (@chars){
    next if $c eq $orig;
    $pwd=$base; substr($pwd,$pos,1)=$c;
    if(crc32("PASSWORD=$pwd\n")==$target){
      print "1-mut pos $pos $orig->$c pwd $pwd\n";
      $found++;
    }
  }
}
print "1-mut done found $found\n";
'
","description":"Brute-force single mutations for CRC match"}

